CREATE OR REPLACE PACKAGE explain_plan AS
  FUNCTION explain_op(p_operation IN VARCHAR2, p_options IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION as_mermaid(p_stmt_id IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION as_tree(p_stmt_id IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION as_story(p_stmt_id IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION analyze(p_query IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE explain_for(p_stmt_id IN VARCHAR2, p_query IN VARCHAR2);
  PROCEDURE show(p_query IN VARCHAR2);
END explain_plan;
